<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><title>Access Logs | A.T.O.M.</title><style>
:root{color-scheme:dark;font-family:Inter,system-ui,sans-serif;background:#080d16;color:#e8eef7;--line:#223044;--muted:#8392a8;--lime:#b7f36b;--cyan:#62d9e8;--red:#ff7188}*{box-sizing:border-box}body{margin:0;min-width:320px;background:radial-gradient(ellipse at 78% -15%,rgba(46,105,130,.2),transparent 38%),#080d16}a{color:inherit;text-decoration:none}.app{min-height:100vh;display:grid;grid-template-columns:230px minmax(0,1fr)}aside{position:sticky;top:0;height:100vh;padding:24px 15px;background:#0a111c;border-right:1px solid var(--line)}.brand{padding:8px 10px 30px;font-weight:900;letter-spacing:.16em}.brand small{display:block;margin-top:5px;color:var(--muted);font-size:9px}nav a{display:block;padding:13px 12px;margin:4px 0;border-radius:9px;color:#91a0b5;font-size:12px}nav a.active{color:var(--lime);background:#1b2b26}.source{position:absolute;bottom:20px;left:15px;right:15px;padding:12px;border:1px solid var(--line);border-radius:10px;color:var(--muted);font-size:9px}.source b{display:block;margin-top:7px;color:var(--lime)}main{min-width:0;padding:30px clamp(16px,3vw,44px)}header{display:flex;justify-content:space-between;gap:15px;align-items:flex-start;padding-bottom:22px;border-bottom:1px solid var(--line)}.eyebrow{color:var(--cyan);font-size:9px;letter-spacing:.18em;font-weight:800}h1{margin:8px 0 5px;font-size:clamp(25px,3vw,34px);letter-spacing:-.05em}.sub{color:var(--muted);font-size:11px}.live{padding:9px 12px;border:1px solid #3d5835;border-radius:8px;color:var(--lime);font-size:9px;font-weight:800}.section{display:flex;justify-content:space-between;gap:12px;margin:25px 0 12px;font-size:12px;font-weight:800}.hint{color:var(--muted);font-size:9px;font-weight:400}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}.stat,.panel{padding:16px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(145deg,#142131,#0d1623)}.stat label{color:#9baabd;font-size:10px}.num{margin-top:10px;font-size:26px;font-weight:800}.green{color:var(--lime)}.red{color:var(--red)}.panel{padding:0;overflow:hidden}.filters{display:flex;flex-wrap:wrap;gap:8px;padding:15px}.field,.btn{min-height:38px;padding:0 11px;border:1px solid #2a3b50;border-radius:8px;background:#0b1522;color:#e8eef7;font:11px Inter,system-ui}.search{width:min(310px,100%)}.btn{display:inline-flex;align-items:center;justify-content:center;background:#1b2b26;color:var(--lime);border-color:#3d5835;font-weight:800}.secondary{background:#142033;color:#aab8ca;border-color:#2a3b50}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th{padding:12px;border-bottom:1px solid #2a394d;color:#718198;font-size:8px;letter-spacing:.12em;text-align:left}td{padding:13px 12px;border-bottom:1px solid #223044;color:#c8d3e1;font-size:10px}tbody tr:last-child td{border:0}.name{font-weight:750;color:#e5edf7}.muted{margin-top:4px;color:#718198;font-size:9px}.pill{display:inline-block;padding:5px 8px;border-radius:6px;background:#1b3024;color:var(--lime);font-size:8px;font-weight:850;text-transform:uppercase}.pill.denied{background:#351d29;color:var(--red)}.detail{color:var(--cyan);font-weight:750;font-size:9px}.empty{text-align:center;color:var(--muted);padding:25px}.pagination{display:flex;justify-content:space-between;align-items:center;padding:14px 15px;border-top:1px solid var(--line);color:var(--muted);font-size:9px}.pagination a{padding:8px;border:1px solid #2a3b50;border-radius:7px}.disabled{opacity:.35;pointer-events:none}footer{margin-top:22px;padding-top:13px;border-top:1px solid var(--line);color:#596a80;font-size:8px}@media(max-width:950px){.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.app{grid-template-columns:60px minmax(0,1fr)}aside{padding:18px 5px}.brand{font-size:0;text-align:center;padding:8px 0 22px}.brand:before{content:'A.';font-size:17px}nav a{padding:12px 5px;text-align:center;font-size:0}nav a:before{content:attr(data-icon);font-size:15px}.source{display:none}main{padding:22px 12px}}@media(max-width:560px){header{flex-direction:column}.filters .field,.filters .btn{flex:1}.search{width:100%}footer{line-height:1.7}}
</style></head><body><div class="app"><aside><div class="brand">A.T.O.M.<small>BIOMETRIC ACCESS</small></div><nav><a href="{{ route('dashboard') }}" data-icon="▦">Overview</a><a href="{{ route('devices.index') }}" data-icon="▣">Devices</a><a href="{{ route('operators.index') }}" data-icon="♙">Operators</a><a class="active" href="{{ route('access-logs.index') }}" data-icon="≡">Access logs</a><a href="#" data-icon="◷">Sessions · Soon</a><a href="#" data-icon="⌁">MQTT · Soon</a></nav><div class="source">DATA SOURCE<b>● Read-only connected</b>atomic_access · monitoring only</div></aside><main>
<header><div><div class="eyebrow">BIOMETRIC ACCESS INTELLIGENCE / AUDIT TRAIL</div><h1>Access Logs</h1><div class="sub">Chronological history of fingerprint access attempts and decisions.</div></div><div class="live">● ACCESS AUDIT</div></header>
