</tbody></table></div><div class="pagination"><span>Page {{ $logs->currentPage() }} of {{ max(1, $logs->lastPage()) }}</span><div><a class="{{ $logs->onFirstPage() ? 'disabled' : '' }}" href="{{ $logs->previousPageUrl() ?: '#' }}">← Previous</a> <a class="{{ $logs->hasMorePages() ? '' : 'disabled' }}" href="{{ $logs->nextPageUrl() ?: '#' }}">Next →</a></div></div></section><footer>A.T.O.M. · Read-only monitoring · Asia/Jakarta</footer></main></div><script>window.setInterval(()=>{if(!document.hidden)window.location.reload()},30000)</script></body></html>